# Shared access to the golden reference fixtures.
#
# The fixtures are generated by soupir_moran_multi() alone (see fixtures/make_golden.R). Everything
# in the package is measured against them. Regenerate with:
#   Rscript tests/testthat/fixtures/make_golden.R

golden_path <- function() {
  p <- testthat::test_path("fixtures", "golden.rds")
  if (!file.exists(p)) {
    testthat::skip("golden.rds missing; run tests/testthat/fixtures/make_golden.R")
  }
  p
}

golden <- function() readRDS(golden_path())

golden_cases <- function() golden()$cases

# Tolerance for agreement with the reference implementation.
#
# Bit-identity is not achievable: the reference computes squared distances as
# as.matrix(dist(coords))^2 -- a square root followed by a square -- while the compute core forms
# dx*dx + dy*dy directly. Those differ by roughly one unit in the last place before exp() amplifies
# them. The measured maximum discrepancy on the fixture set is recorded in
# test-reference-agreement.R; this constant is the assertion threshold, set well above the measured
# value but far below anything that could mask a real error.
REFERENCE_TOLERANCE <- 1e-12

# A bandwidth is degenerate when almost every cell carries near-full weight: the kernel becomes a
# constant matrix and Moran's I collapses toward zero, so agreement between two implementations
# proves nothing. Earlier validation in this repository ran entirely inside this regime because
# ccRCCExample's coordinates are in millimetres, and h = 10..250 sits entirely inside that regime.
MAX_SATURATION <- 0.80   # mean row sum as a fraction of N
